<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, computed } from 'vue';
import { io, type Socket } from 'socket.io-client';
import { UsersRound, UserCheck, UserRoundMinus, Clock3, ArrowRight, Activity, RefreshCw, ScanFace } from 'lucide-vue-next';
import { api, time, labels, fullDate, today } from '../api';
const data = ref<any>(null), error = ref(''), loading = ref(true), connected = ref(false); let socket: Socket | undefined; let poll: ReturnType<typeof setInterval>;
const stats = computed(() => [ { label: 'Total employees', value: data.value?.total ?? 0, icon: UsersRound, tone: 'blue', note: 'Active in the directory' }, { label: 'Present today', value: data.value?.present ?? 0, icon: UserCheck, tone: 'green', note: `${data.value?.rate ?? 0}% of all employees` }, { label: 'Not yet clocked in', value: data.value?.absent ?? 0, icon: UserRoundMinus, tone: 'orange', note: 'Scheduled employees' }, { label: 'Late arrivals', value: data.value?.late ?? 0, icon: Clock3, tone: 'rose', note: 'Based on assigned schedule' } ]);
async function load() { try { data.value = await api('/dashboard'); error.value = ''; } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } }
onMounted(() => { void load(); socket = io({ withCredentials: true }); socket.on('connect', () => connected.value = true); socket.on('disconnect', () => connected.value = false); socket.on('attendance:changed', load); poll = setInterval(load, 30000); });
onBeforeUnmount(() => { socket?.disconnect(); clearInterval(poll); });
</script>
<template>
  <p v-if="error" class="alert error" role="alert">{{ error }} <button class="text-button" @click="load">Try again</button></p>
  <section class="overview-banner"><div><span class="banner-kicker">TODAY AT SAN JUAN</span><h2>Every workday counts.</h2><p>Keep your team in view and your time records in order.</p></div><div class="banner-date"><CalendarIllustration /><span>{{ fullDate(data?.date ?? today()) }}</span></div><div class="banner-pattern" aria-hidden="true"><ScanFace :size="126" :stroke-width="0.7" /></div></section>
  <div class="section-toolbar"><h2>Today’s attendance <span class="live-badge" :class="{ offline: !connected }"><span />{{ connected ? 'Live updates' : 'Updates every 30s' }}</span></h2><button class="text-button" @click="load"><RefreshCw :size="14" /> Refresh</button></div>
  <div class="stats-grid"><article v-for="stat in stats" :key="stat.label" class="stat-card"><div class="stat-top"><span>{{ stat.label }}</span><div :class="['stat-icon', stat.tone]"><component :is="stat.icon" :size="19" /></div></div><strong class="stat-number">{{ loading ? '—' : stat.value }}</strong><small>{{ stat.note }}</small></article></div>
  <div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Recent activity</h2><p>Attendance events as they happen</p></div><RouterLink class="text-button" to="/attendance">View all <ArrowRight :size="16" /></RouterLink></div><div v-if="!data?.feed?.length" class="empty-state"><Activity :size="32" /><h3>{{ loading ? 'Loading attendance…' : 'A fresh start for today' }}</h3><p>Clock-ins and clock-outs will appear here.<br>Register your employees to get started.</p><RouterLink v-if="!loading" class="button secondary" to="/employees">Open employee directory</RouterLink></div><div v-else class="table-wrap"><table><thead><tr><th>Employee</th><th>Event</th><th>Time</th><th>Source</th></tr></thead><tbody><tr v-for="p in data.feed.filter((p: any) => !p.voidedAt).slice(0, 8)" :key="p.id"><td><div class="person-cell"><div class="avatar small">{{ p.employee.firstName[0] }}{{ p.employee.lastName[0] }}</div><div><strong>{{ p.employee.firstName }} {{ p.employee.lastName }}</strong><small>{{ p.employee.department }}</small></div></div></td><td><span :class="['badge', p.kind.endsWith('IN') ? 'green' : 'neutral']">{{ labels[p.kind] }}</span></td><td class="numeric">{{ time(p.occurredAt) }}</td><td><span class="source-label">{{ p.source === 'FACE' ? 'Face scan' : 'Manual' }}</span></td></tr></tbody></table></div></section>
  <section class="panel department-panel"><div class="panel-heading"><div><h2>By department</h2><p>Present / active employees</p></div><UsersRound :size="19" class="muted" /></div><div v-if="!data?.departments?.length" class="empty-state compact"><UsersRound :size="28" /><p>Your departments will appear<br>as you add employees.</p></div><div v-else class="department-list"><div v-for="d in data.departments" :key="d.name" class="department-item"><div><strong>{{ d.name }}</strong><span>{{ d.present }} <small>/ {{ d.total }}</small></span></div><div class="progress-track"><span :style="{ width: `${d.total ? d.present / d.total * 100 : 0}%` }" /></div></div></div><div class="department-note"><ShieldIcon /><span>Records are visible to authorized<br>municipal personnel.</span></div></section></div>
  <section class="quick-links"><RouterLink to="/employees"><div class="quick-icon"><UsersRound :size="21" /></div><div><strong>Manage your people</strong><small>Employee details & face enrollment</small></div><ArrowRight :size="18" /></RouterLink><RouterLink to="/reports"><div class="quick-icon"><Clock3 :size="21" /></div><div><strong>Prepare a time record</strong><small>Monthly DTR preview & PDF export</small></div><ArrowRight :size="18" /></RouterLink></section>
</template>
<script lang="ts">
import { CalendarDays as CalendarIllustration, ShieldCheck as ShieldIcon } from 'lucide-vue-next';
export default { components: { CalendarIllustration, ShieldIcon } };
</script>
